// Des: Tests reminders: fill once, dry run, bad input
// Flo: mock chat page > remind in each mode > read the page reminder list
// I/O: html > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const rem = @import("ru-chat-remi.zig"); const sess = @import("ru-sess-ctxz.zig"); const data = @import("st-stat-data.zig"); const conf = @import("cf-conf-load.zig"); const mock = @import("te-mock-page.zig"); const snap = @import("ru-page-snap.zig"); const fixt = @import("te-fixt-html.zig"); const T = std.testing;
const NOON: i64 = 100 * 86400000 + 12 * 3600000;
fn profOf(tmpz: *std.testing.TmpDir, buff: []u8) ![]const u8 { return std.fmt.bufPrint(buff, ".zig-cache/tmp/{s}/prof", .{tmpz.sub_path}); }
fn cfgOf() conf.Conf { var cfg: conf.Conf = .{}; cfg.type_dely_msec = .{ 1, 2 }; cfg.warm_dayz_coun = 0; cfg.retr_coun_maxz = 2; return cfg; }
test "M6 live: reminder dialog is filled with Vietnamese title and time, created once" { var buff: [160]u8 = undefined; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var mok = try mock.start(T.allocator, T.io, try profOf(&tmpz, &buff), fixt.chat); defer mok.stop(); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); var sto = try data.Stor.open(T.allocator, ":memory:"); defer sto.close(); var ses = sess.Sess.init(T.allocator, T.io, aren.allocator(), cfgOf(), &sto, mok.conn, .live); ses.fast = true; ses.fake_ms = NOON; ses.job = "remi"; try T.expect(try rem.remind(&ses, "Mom", "Gọi điện cho mẹ", "20:00")); try T.expectEqualStrings("1", try snap.evalStr(aren.allocator(), mok.conn, "rems.length")); try T.expectEqualStrings("Gọi điện cho mẹ|20:00", try snap.evalStr(aren.allocator(), mok.conn, "rems[0]")); }
test "dry run previews and the dialog stays closed" { var buff: [160]u8 = undefined; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var mok = try mock.start(T.allocator, T.io, try profOf(&tmpz, &buff), fixt.chat); defer mok.stop(); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); var sto = try data.Stor.open(T.allocator, ":memory:"); defer sto.close(); var ses = sess.Sess.init(T.allocator, T.io, aren.allocator(), cfgOf(), &sto, mok.conn, .dry); ses.fast = true; ses.fake_ms = NOON; ses.job = "remi"; try T.expect(!try rem.remind(&ses, "Mom", "x", "8")); try T.expectEqualStrings("0", try snap.evalStr(aren.allocator(), mok.conn, "rems.length")); try T.expectEqualStrings("none", try snap.evalStr(aren.allocator(), mok.conn, "rem.style.display")); }
test "bad input and read-only mode" { var buff: [160]u8 = undefined; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var mok = try mock.start(T.allocator, T.io, try profOf(&tmpz, &buff), fixt.chat); defer mok.stop(); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); var sto = try data.Stor.open(T.allocator, ":memory:"); defer sto.close(); var ses = sess.Sess.init(T.allocator, T.io, aren.allocator(), cfgOf(), &sto, mok.conn, .live); ses.fast = true; ses.fake_ms = NOON; try T.expectError(error.BadJob, rem.remind(&ses, "", "x", "8")); try T.expectError(error.BadJob, rem.remind(&ses, "Mom", "  ", "8")); try T.expectError(error.BadJob, rem.remind(&ses, "Mom", "x", "")); ses.mode = .read; try T.expectError(error.BadUsage, rem.remind(&ses, "Mom", "x", "8")); ses.mode = .live; try T.expectError(error.NoElem, rem.remind(&ses, "Nobody", "x", "8")); }
